  Ciphertext s3 = t2 * c2 - c6t2;            // level 3
  Ciphertext s4 = t3 * c3 - t3 * c5;         // level 4
  Ciphertext s = s2 + (s3 + s4);

  Ciphertext result = w + s + c0;
  result.set_output("y");
